-- Isolated PostgreSQL fixture only: photo RLS, transitions, revisions and imports.
begin;
insert into auth.users(id) values('11111111-1111-1111-1111-111111111111'),('22222222-2222-2222-2222-222222222222');
update daily_deck_private.auth_configuration set mode='preview';
create function test_support.cloud(op text,args jsonb default '{}',rev bigint default null,req uuid default gen_random_uuid()) returns jsonb language sql as $$
 select public.daily_deck_sync(auth.uid(),op,req,coalesce(rev,(select revision from public.daily_deck_sync_heads where owner_id=auth.uid()),0),case when op='read' then args else args||jsonb_build_object('localDay',current_date::text) end,'UTC')
$$;
grant execute on function test_support.cloud(text,jsonb,bigint,uuid) to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-1111-1111-111111111111',true);
select public.daily_deck_complete_preview_onboarding(auth.uid(),true,true,false);
select set_config('test.meta','{"source_extension":"png","source_width":800,"source_height":400,"source_bytes":1000,"rendered_width":800,"rendered_bytes":500,"crop_x":0.4,"crop_y":0.5,"crop_zoom":2}',true);
select public.daily_deck_photo(auth.uid(),'aaaaaaaa-0000-0000-0000-000000000090',current_setting('test.meta')::jsonb);
select public.daily_deck_photo(auth.uid(),'aaaaaaaa-0000-0000-0000-000000000090',current_setting('test.meta')::jsonb);
select test_support.assert_true((select count(*)=1 from public.daily_deck_photos),'photo registration retry is idempotent');
select test_support.expect_error($q$select public.daily_deck_photo(auth.uid(),'aaaaaaaa-0000-0000-0000-000000000090',current_setting('test.meta')::jsonb||'{"crop_zoom":3}')$q$,array['23505'],'photo ID cannot overwrite crop metadata');
select test_support.expect_error($q$select public.daily_deck_photo(auth.uid(),'aaaaaaaa-0000-0000-0000-000000000099',current_setting('test.meta')::jsonb||'{"source_bytes":20971521}')$q$,array['23514'],'original size limit enforced');
select test_support.expect_error($q$select public.daily_deck_photo(auth.uid(),'aaaaaaaa-0000-0000-0000-000000000099',current_setting('test.meta')::jsonb||'{"source_extension":"svg"}')$q$,array['23514'],'unsupported image type rejected');
select test_support.expect_error($q$select public.daily_deck_photo(auth.uid(),'aaaaaaaa-0000-0000-0000-000000000099',current_setting('test.meta')::jsonb||'{"rendered_bytes":1048577}')$q$,array['23514'],'crop size limit enforced');
select set_config('test.task',jsonb_build_object('task',jsonb_build_object('id','aaaaaaaa-0000-0000-0000-000000000001','kind','today','title','Photo task','notes','Preserve photo history','minutes',null,'weekdays','[]'::jsonb,'icon','neutral','photoId','aaaaaaaa-0000-0000-0000-000000000090','deadline','14:00','remind',true))::text,true);
select test_support.expect_error('select test_support.cloud(''save'',current_setting(''test.task'')::jsonb)',array['23514'],'incomplete source/crop uploads cannot become task references');
insert into storage.objects(bucket_id,name,metadata) values('daily-deck-photos',auth.uid()||'/aaaaaaaa-0000-0000-0000-000000000090/original.png','{"size":1000,"mimetype":"image/png"}'),('daily-deck-photos',auth.uid()||'/aaaaaaaa-0000-0000-0000-000000000090/card.jpg','{"size":500,"mimetype":"image/jpeg"}');
select test_support.cloud('save',current_setting('test.task')::jsonb);
select test_support.expect_error($q$select public.daily_deck_photo(auth.uid(),'aaaaaaaa-0000-0000-0000-000000000090',null,true)$q$,array['23503'],'referenced photo cleanup blocked');
select public.daily_deck_photo(auth.uid(),'aaaaaaaa-0000-0000-0000-000000000091',current_setting('test.meta')::jsonb);
insert into storage.objects(bucket_id,name,metadata) values('daily-deck-photos',auth.uid()||'/aaaaaaaa-0000-0000-0000-000000000091/original.png','{"size":1000,"mimetype":"image/png"}'),('daily-deck-photos',auth.uid()||'/aaaaaaaa-0000-0000-0000-000000000091/card.jpg','{"size":500,"mimetype":"image/jpeg"}');
select test_support.cloud('save',jsonb_set(current_setting('test.task')::jsonb,'{task,photoId}','"aaaaaaaa-0000-0000-0000-000000000091"'));
select test_support.assert_true((select photo_id='aaaaaaaa-0000-0000-0000-000000000090' from public.daily_deck_occurrences),'replacement keeps original occurrence photo snapshot');
select test_support.assert_true((select photo_id='aaaaaaaa-0000-0000-0000-000000000091' from public.daily_deck_appearance_versions),'replacement appends new appearance');
select test_support.expect_error($q$select public.daily_deck_photo(auth.uid(),'aaaaaaaa-0000-0000-0000-000000000090',null,true)$q$,array['23503'],'historical source remains protected after replacement');
select set_config('test.card',(select id::text from public.daily_deck_occurrences),true);
select test_support.cloud('action',jsonb_build_object('cardId',current_setting('test.card'),'action','done'));
select test_support.cloud('save',jsonb_set(current_setting('test.task')::jsonb,'{task,deadline}','"16:00"'));
select test_support.assert_true((select deadline_local=time '14:00' from public.daily_deck_occurrences),'completed deadline snapshot remains unchanged');
select public.daily_deck_photo(auth.uid(),'aaaaaaaa-0000-0000-0000-000000000092',current_setting('test.meta')::jsonb);
insert into storage.objects(bucket_id,name,metadata) values('daily-deck-photos',auth.uid()||'/aaaaaaaa-0000-0000-0000-000000000092/original.png','{"size":1000,"mimetype":"image/png"}');
select test_support.assert_true((test_support.affected('delete from storage.objects where name like ''%000000000092%'''))=0,'partial upload protected until metadata cleanup');
select public.daily_deck_photo(auth.uid(),'aaaaaaaa-0000-0000-0000-000000000092',null,true);
select test_support.assert_true((test_support.affected('delete from storage.objects where name like ''%000000000092%'''))=1,'orphan bytes can be cleaned after unused metadata removal');
-- Weekday exclusion, tomorrow-effective revisions, deleted pending/future occurrences.
select test_support.cloud('save',jsonb_build_object('task',jsonb_build_object('id','aaaaaaaa-0000-0000-0000-000000000002','kind','habit','title','Other weekday','notes','','minutes',null,'weekdays',jsonb_build_array((extract(dow from current_date)::int+1)%7),'icon','read')));
select test_support.assert_true((select count(*)=0 from public.daily_deck_occurrences where item_id='aaaaaaaa-0000-0000-0000-000000000002'),'other-day habit excluded today');
select test_support.cloud('save',jsonb_build_object('task',jsonb_build_object('id','aaaaaaaa-0000-0000-0000-000000000003','kind','habit','title','Every day','notes','','minutes',null,'weekdays','[0,1,2,3,4,5,6]'::jsonb,'icon','water')));
select set_config('test.habitcard',(select id::text from public.daily_deck_occurrences where item_id='aaaaaaaa-0000-0000-0000-000000000003' and scheduled_on=current_date),true);
select test_support.cloud('action',jsonb_build_object('cardId',current_setting('test.habitcard'),'action','later'));
reset role;
select daily_deck_private.reconcile('11111111-1111-1111-1111-111111111111',current_date+1);
select daily_deck_private.reconcile('11111111-1111-1111-1111-111111111111',current_date+1);
set local role authenticated;
select test_support.assert_true((select count(*)=2 from public.daily_deck_occurrences where item_id='aaaaaaaa-0000-0000-0000-000000000003'),'midnight catch-up creates exactly one next occurrence');
select test_support.cloud('save',jsonb_build_object('task',jsonb_build_object('id','aaaaaaaa-0000-0000-0000-000000000003','kind','habit','title','Edited future','notes','','minutes',null,'weekdays','[0,1,2,3,4,5,6]'::jsonb,'icon','water')));
select test_support.assert_true((select max(effective_from)=current_date+2 from public.daily_deck_schedule_versions where item_id='aaaaaaaa-0000-0000-0000-000000000003'),'edit respects tomorrow/previously visited date boundary');
select test_support.assert_true((select bool_and(title='Every day') from public.daily_deck_occurrences where item_id='aaaaaaaa-0000-0000-0000-000000000003'),'existing occurrence text is not rewritten');
select test_support.cloud('delete','{"taskId":"aaaaaaaa-0000-0000-0000-000000000003"}');
select test_support.assert_true((select count(*)=2 from public.daily_deck_events where action='delete'),'postponed today and pre-generated future occurrences both deleted');
select test_support.assert_true((select count(*)=1 from public.daily_deck_events where action='done'),'habit deletion never counts as completion');
select test_support.expect_error('select test_support.cloud(''undo'',jsonb_build_object(''eventId'',(select id from public.daily_deck_events where action=''later'' and occurrence_id=current_setting(''test.habitcard'')::uuid)))',array['40001'],'deleted habit cannot be revived by Undo');
select public.daily_deck_sync(auth.uid(),'read',gen_random_uuid(),0,'{}','Pacific/Kiritimati');
select public.daily_deck_sync(auth.uid(),'read',gen_random_uuid(),0,'{}','Pacific/Honolulu');
select test_support.assert_true((select count(*)=count(distinct(item_id,scheduled_on)) from public.daily_deck_occurrences),'timezone changes never duplicate civil-date pairs');
-- Cross-user private-photo reads/writes fail, including malicious IDs.
select set_config('request.jwt.claim.sub','22222222-2222-2222-2222-222222222222',true);
select public.daily_deck_complete_preview_onboarding(auth.uid(),true,true,false);
select test_support.assert_true((select count(*)=0 from public.daily_deck_photos),'B cannot read A metadata');
select test_support.assert_true((select count(*)=0 from storage.objects where bucket_id='daily-deck-photos'),'B cannot read A private photo objects');
select test_support.expect_error($q$insert into storage.objects(bucket_id,name) values('daily-deck-photos','11111111-1111-1111-1111-111111111111/aaaaaaaa-0000-0000-0000-000000000090/extra.png')$q$,array['42501'],'B cannot upload into A prefix');
select test_support.assert_true(test_support.affected('delete from storage.objects where bucket_id=''daily-deck-photos''')=0,'B cannot remove A bytes');
select test_support.expect_error($q$select public.daily_deck_photo('11111111-1111-1111-1111-111111111111','aaaaaaaa-0000-0000-0000-000000000090',null,true)$q$,array['42501'],'spoofed cleanup identity denied');
select test_support.expect_error('select test_support.cloud(''save'',current_setting(''test.task'')::jsonb)',array['23514'],'B cannot attach A photo UUID');
-- Atomic import retains historical dates, timestamps, deadlines and event order.
select set_config('test.import',jsonb_build_object('deck',jsonb_build_object('version',1,'tasks',jsonb_build_array(jsonb_build_object('id','bbbbbbbb-0000-0000-0000-000000000001','kind','today','title','Imported legacy','notes','Old notes','minutes',15,'weekdays','[]'::jsonb,'created',(current_date-2)::text,'archived',false,'icon','neutral')),'cards',jsonb_build_array(jsonb_build_object('id','bbbbbbbb-0000-0000-0000-000000000002','taskId','bbbbbbbb-0000-0000-0000-000000000001','habit',false,'day',(current_date-2)::text,'title','Old snapshot','notes','Old snapshot notes','minutes',15,'initialOrder',3,'icon','neutral','events',jsonb_build_array(jsonb_build_object('id','bbbbbbbb-0000-0000-0000-000000000003','action','later','at','2026-01-01T10:00:00Z','day',(current_date-1)::text,'order',9,'sequence',1),jsonb_build_object('id','bbbbbbbb-0000-0000-0000-000000000004','action','done','at','2026-01-01T10:01:00Z','day',(current_date-1)::text,'order',9,'sequence',2))))))::text,true);
select set_config('test.importid',gen_random_uuid()::text,true);
select test_support.cloud('import',current_setting('test.import')::jsonb,0,current_setting('test.importid')::uuid);
select test_support.cloud('import',current_setting('test.import')::jsonb,0,current_setting('test.importid')::uuid);
select test_support.assert_true((select count(*)=1 from public.daily_deck_items),'repeated import creates no duplicates');
select test_support.assert_true((select count(*)=2 from public.daily_deck_events),'import retains Later followed by Done');
select test_support.assert_true((select title='Old snapshot' and notes='Old snapshot notes' and legacy_minutes=15 and deadline_local is null from public.daily_deck_occurrences),'legacy snapshots preserved; duration is never a deadline');
select test_support.assert_true((select occurred_at=timestamptz '2026-01-01T10:01:00Z' from public.daily_deck_events where action='done'),'import retains exact completion instant');
select test_support.assert_true((select scheduled_on=current_date-2 from public.daily_deck_occurrences),'import retains original civil date');
select test_support.expect_error('select test_support.cloud(''import'',current_setting(''test.import'')::jsonb)',array['23514'],'new import ID cannot replace the existing deck');
select test_support.assert_true((select count(*)=1 from public.daily_deck_items),'B cannot see A records after importing');
select set_config('request.jwt.claim.sub','11111111-1111-1111-1111-111111111111',true);
select test_support.assert_true((select count(*)=3 from public.daily_deck_items),'A cannot see B imported task');
rollback;
